* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--color-bg-primary);
  color: var(--color-text-primary);
  font-family: var(--font-family-base);
  font-size: var(--font-size-base);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ============================================================================
   Utility Classes
   ============================================================================ */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ============================================================================
   Main Layout & Image Preview
   ============================================================================ */

#app {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

.image-preview {
  width: 100%;
  max-width: 800px;
}

.image-container {
  background-color: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 0;
  overflow: hidden;
  box-shadow: var(--shadow-md);
}

.preview-image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 400px;
  object-fit: cover;
  background-color: var(--color-bg-tertiary);
}

.image-info {
  padding: 2rem;
}

.image-info h1 {
  font-size: var(--font-size-xl);
  color: var(--color-text-primary);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.image-details {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  margin-bottom: 1rem;
}

.image-details span {
  display: inline;
}

.image-description {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

/* ============================================================================
   Buttons
   ============================================================================ */

button {
  font-family: inherit;
  font-size: inherit;
  cursor: pointer;
  border: none;
  outline: none;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.delete-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.875rem 1.5rem;
  background-color: var(--color-danger);
  color: white;
  font-weight: 500;
  border-radius: 6px;
  transition: all var(--transition-fast);

  /* Focus visible styles */
  position: relative;
}

.delete-btn:hover:not(:disabled) {
  background-color: var(--color-danger-hover);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.3);
}

.delete-btn:active:not(:disabled) {
  transform: translateY(0);
}

.delete-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.delete-icon {
  font-size: 1.125rem;
}

