.btn {
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  font-weight: 500;
  transition: all var(--transition-fast);
  flex: 1;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-secondary {
  background-color: var(--color-bg-tertiary);
  color: var(--color-text-primary);
  border: 1px solid var(--color-border);
}

.btn-secondary:hover:not(:disabled) {
  background-color: rgba(255, 255, 255, 0.1);
  border-color: var(--color-text-secondary);
}

.btn-danger {
  background-color: var(--color-danger);
  color: white;
}

.btn-danger:hover:not(:disabled) {
  background-color: var(--color-danger-hover);
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.3);
}

/* ============================================================================
   Dialog Modal Styles
   ============================================================================ */

dialog {
  border: none;
  border-radius: 12px;
  background-color: var(--color-bg-secondary);
  color: var(--color-text-primary);
  box-shadow: var(--shadow-lg);
  max-width: 500px;
  width: 90vw;
  padding: 0;

  /* Ensure dialog doesn't overflow */
  max-height: 90vh;
  overflow-y: auto;
}

/* Backdrop for dialog */
dialog::backdrop {
  background-color: var(--color-overlay);
  backdrop-filter: blur(4px);
}

/* Reset default dialog styles for non-supporting browsers */
dialog[open] {
  display: flex;
  flex-direction: column;
}

.dialog-content {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.dialog-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  color: var(--color-text-primary);
  margin: 0;
}

.dialog-description {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin: 0;
}

.dialog-actions {
  display: flex;
  gap: 1rem;
  margin-top: 1rem;
}

.dialog-actions .btn {
  flex: 1;
}

/* Ensure dialog is not visible by default */
dialog:not([open]) {
  display: none;
}

/* ============================================================================
   Animations
   ============================================================================ */

@keyframes slideIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

dialog[open] {
  animation: slideIn var(--transition-standard);
