        <div style="font-size: 2rem; margin-bottom: 1rem;">✓</div>
        <h2 style="margin-bottom: 0.5rem;">Image Deleted</h2>
        <p style="color: var(--color-text-secondary); margin-bottom: 1.5rem;">
          "Mountain Sunrise" has been removed from your library.
        </p>
        <button onclick="location.reload()" class="trigger" style="background-color: var(--color-accent);">
          Return to Gallery
        </button>
      </div>
    `;
  }
}

// Initialize the dialog component when DOM is ready
