 * Modal Dialog Component
 * Manages the delete confirmation dialog with proper accessibility support
 */

class DeleteConfirmDialog {
  constructor() {
    this.dialog = document.getElementById('deleteConfirmDialog');
    this.triggerBtn = document.querySelector('.trigger');
    this.cancelBtn = document.getElementById('cancelBtn');
    this.confirmBtn = document.getElementById('confirmBtn');
    this.statusMessage = document.getElementById('statusMessage');

    // Store the element that triggered the dialog for focus restoration
    this.previouslyFocused = null;

    this.init();
  }

  init() {
    // Open dialog when trigger button is clicked
    this.triggerBtn.addEventListener('click', () => this.openDialog());

    // Close dialog with cancel button
    this.cancelBtn.addEventListener('click', () => this.closeDialog());

    // Handle confirm button
    this.confirmBtn.addEventListener('click', () => this.handleConfirm());

    // Close dialog when Escape key is pressed
    this.dialog.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        this.closeDialog();
      }
    });

    // Close dialog when clicking outside (on backdrop)
    this.dialog.addEventListener('click', (e) => {
      if (e.target === this.dialog) {
        this.closeDialog();
      }
    });
  }

  openDialog() {
    // Store the element that will receive focus when dialog closes
    this.previouslyFocused = document.activeElement;

    // Show the dialog
    this.dialog.showModal();

    // Announce to screen readers
    this.statusMessage.textContent = 'Delete confirmation dialog opened. Press Escape to cancel.';

    // Set focus to confirm button for keyboard users
    // This ensures keyboard navigation starts at the primary action
    setTimeout(() => {
      this.cancelBtn.focus();
    }, 100);
  }

  closeDialog() {
    // Hide the dialog
    this.dialog.close();

    // Announce to screen readers
    this.statusMessage.textContent = 'Dialog closed.';

    // Restore focus to the trigger button
    if (this.previouslyFocused && this.previouslyFocused.focus) {
      // Use setTimeout to ensure focus happens after dialog closes
      setTimeout(() => {
        this.previouslyFocused.focus();
      }, 0);
    }
  }

  handleConfirm() {
    // Show success message
    this.statusMessage.textContent = 'Image deleted successfully from library.';

    // Close the dialog
    this.closeDialog();

    // In a real application, this would make an API call
    // For now, we'll update the UI to show the image was deleted
    const imageContainer = document.querySelector('.image-container');
    imageContainer.innerHTML = `
      <div class="deletion-confirmation" style="padding: 3rem; text-align: center;">
        <div style="font-size: 2rem; margin-bottom: 1rem;">✓</div>
        <h2 style="margin-bottom: 0.5rem;">Image Deleted</h2>
        <p style="color: var(--color-text-secondary); margin-bottom: 1.5rem;">
          "Mountain Sunrise" has been removed from your library.
        </p>
        <button onclick="location.reload()" class="trigger" style="background-color: var(--color-accent);">
          Return to Gallery
        </button>
      </div>
    `;
  }
}

// Initialize the dialog component when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    new DeleteConfirmDialog();
  });
} else {
  new DeleteConfirmDialog();
}
